import os
import queue
import threading
from typing import Callable, Optional

import azure.cognitiveservices.speech as speechsdk


class StreamingSpeechToText:
    def __init__(
        self,
        on_partial: Optional[Callable[[str], None]] = None,
        on_final: Optional[Callable[[str], None]] = None,
        language: str = "en-US",
    ):
        self.on_partial = on_partial or (lambda text: None)
        self.on_final = on_final or (lambda text: None)
        self.language = language
        self._stop_event = threading.Event()
        self._audio_queue: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._recognized_text = []
        self._recognizing_text = []

        key = os.getenv("AZURE_SPEECH_KEY")
        region = os.getenv("AZURE_SPEECH_REGION")
        if not key or not region:
            raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION must be set")

        self._speech_config = speechsdk.SpeechConfig(subscription=key, region=region)
        self._speech_config.speech_recognition_language = language

        stream_format = speechsdk.audio.AudioStreamFormat(samples_per_second=16000, bits_per_sample=16, channels=1)
        self._push_stream = speechsdk.audio.PushAudioInputStream(stream_format)
        self._audio_config = speechsdk.audio.AudioConfig(stream=self._push_stream)
        self._recognizer = speechsdk.SpeechRecognizer(
            speech_config=self._speech_config,
            audio_config=self._audio_config,
        )

        self._recognizer.recognizing.connect(self._handle_recognizing)
        self._recognizer.recognized.connect(self._handle_recognized)
        self._recognizer.canceled.connect(self._handle_canceled)
        self._recognizer.session_stopped.connect(self._handle_session_stopped)

    def _handle_recognizing(self, evt):
        text = evt.result.text.strip()
        if text:
            self._recognizing_text.append(text)
            self.on_partial(text)

    def _handle_recognized(self, evt):
        if evt.result.reason == speechsdk.ResultReason.RecognizedSpeech:
            text = evt.result.text.strip()
            if text:
                self._recognized_text.append(text)
                self.on_final(text)

    def _handle_canceled(self, evt):
        self._stop_event.set()
        details = getattr(evt, "result", None)
        if details and getattr(details, "reason", None) == speechsdk.CancellationReason.Error:
            error = getattr(details, "error_details", "")
            if error:
                self.on_final(f"[canceled] {error}")

    def _handle_session_stopped(self, evt):
        self._stop_event.set()

    def feed_audio(self, audio_chunk: bytes) -> None:
        if self._stop_event.is_set():
            return
        self._push_stream.write(audio_chunk)

    def end_audio(self) -> None:
        try:
            self._push_stream.close()
        finally:
            self._stop_event.set()

    def start(self) -> None:
        self._recognizer.start_continuous_recognition_async().get()

    def stop(self) -> None:
        self._stop_event.set()
        try:
            self._recognizer.stop_continuous_recognition_async().get()
        finally:
            try:
                self._push_stream.close()
            except Exception:
                pass

    def transcribed_text(self) -> str:
        return " ".join(self._recognized_text).strip()

    def partial_text(self) -> str:
        return " ".join(self._recognizing_text).strip()


def stream_from_file(path: str, chunk_size: int = 3200):
    with open(path, "rb") as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            yield chunk


def recognize_streaming_audio(
    audio_source,
    on_partial: Optional[Callable[[str], None]] = None,
    on_final: Optional[Callable[[str], None]] = None,
    language: str = "en-US",
) -> str:
    recognizer = StreamingSpeechToText(on_partial=on_partial, on_final=on_final, language=language)
    recognizer.start()
    try:
        for chunk in audio_source:
            if not chunk:
                continue
            recognizer.feed_audio(chunk)
        recognizer.end_audio()
    finally:
        recognizer.stop()
    return recognizer.transcribed_text()
